L000233	\end{equation}
L000234	in Fig. \ref{fig:ebm} (a). Each party prepares an entanglement state using a controlled phase gate $C_\pi$
L000235	\begin{equation} \label{eq:controlled_phase_gate}
L000236	C_\pi = \ket{0}\bra{0}U_0 + \ket{1}\bra{1}U_\pi
L000237	\end{equation}
L000238	between the virtual qubit and the coherent state, where $U_{0(\pi)}$ will attach a phase of $0(\pi)$ to the coherent state. The entanglement state prepared by the $m$-th participant is
L000239	\begin{equation} \label{eq:WCP}
L000240	\ket{\Psi}_m = \frac{1}{\sqrt{2}} \left( \ket{0}\ket{e^{\i \phi}\sqrt{\mu_m}} + \ket{1}\ket{e^{\i (\phi+\pi)}\sqrt{\mu_m}} \right),
L000241	\end{equation}
L000242	where the coherent state is sent to an untrusted party to perform interference measurement with the coherent state prepared by other parties, while the virtual qubit is kept at each party.
L000243	\begin{widetext}
L000244	
