L000402	&\left( \frac{1}{2} \right)^{\frac{3}{2}} \left( \frac{1}{d} \right)^2 \sum_{j_1=0}^{d-1}\sum_{j_2=0}^{d-1}\sum_{j_a=0}^{d-1}\sum_{k=0}^{d-1}e^{-2\pi \i  k j_a/d}\\
L000403	&\ket{k}_{A_0}
L000404	\left( \ket{0}_{A_1}\ket{-e^{2\pi \i  j_a /d}\alpha}_A + \ket{1}_{A_1}\ket{-e^{2\pi \i  j_a /d}\alpha} _A\right) \\
L000405	& \ket{j_1}_{B_0}\left( \ket{0}_{B_1}\ket{e^{2\pi \i  (j_1+j_a) /d}\beta}_B + \ket{1}_{B_1}\ket{-e^{2\pi \i  (j_1+j_a) /d}\beta}_B \right)\\
L000406	&\ket{j_2}_{C_0}\left( \ket{0}_{C_1}\ket{e^{2\pi \i  (j_2+j_a) /d}\gamma}_C + \ket{1}_{C_1}\ket{-e^{2\pi \i  (j_2+j_a) /d}\gamma}_C \right),
L000407	\end{split}
L000408	\end{equation}
L000409	where
L000410	\begin{equation}
L000411	F^\dagger = \frac{1}{\sqrt{d}}\sum_{j=0}^{d-1}\sum_{k=0}^{d-1}e^{-2\pi \i j k/d}\ket{k}\bra{j}.
L000412	\end{equation}
L000413	Subsequent to the implementation of projective measurements on the auxiliary systems $A_0$, $B_0$, and $C_0$ in their respective basis, the final system evolves into
L000414	
L000415	\begin{equation}
L000416	\begin{split}
L000417	&
L000418	\sum_{j_a = 0}^{d-1} e^{-2\pi \i kj_a/d}
L000419	\left( \ket{0}_{A_1} \ket{e^{2\pi \i  j_a /d}\alpha}_A + \ket{1}_{A_1} \ket{-e^{2\pi \i  j_a /d}\alpha}_A \right) \\
L000420	&
L000421	\left( \ket{0}_{B_1} \ket{e^{2\pi \i  j_a /d}\beta '}_B + \ket{1}_{B_1} \ket{-e^{2\pi \i  j_a /d}\beta '}_B \right)
L000422	\left( \ket{0}_{C_1} \ket{e^{2\pi \i  j_a /d}\gamma '}_C + \ket{1}_{C_1} \ket{-e^{2\pi \i  j_a /d}\gamma '}_C \right) \\
L000423	&
L000424	= e^{-(|\alpha|^2+|\beta|^2+|\gamma|^2)/2} \sum_{j_a=0}^{d-1} \sum_{n=0}^{\infty}\sum_{m=0}^{\infty}\sum_{l=0}^{\infty} e^{2\pi \i (n+m+l-k)j_a/d}\\
L000425	&
L000426	\left[\ket{0}+(-1)^n\ket{1}\right]_{A_1}
L000427	\left[\ket{0}+(-1)^m\ket{1}\right]_{B_1}
L000428	\left[\ket{0}+(-1)^l\ket{1}\right]_{C_1} \frac{\alpha^n\beta'^m\gamma'^l}{\sqrt{n!m!l!}}\ket{nml}_{ABC}.
L000429	\end{split}
L000430	\end{equation}
L000431	\end{widetext}
L000432	Here, $e^{2\pi\i j_b/d}\beta$ is denoted as $\beta'$ and $e^{2\pi\i j_c/d}\gamma$ is denoted as $\gamma'$ for clarity. After performing the interference measurement on coherent state, if $n+m+l$ is even (odd), the state shared by Alice, Bob and Charlie is the linear combination of $\frac{1}{\sqrt{2}}\left(\ket{0 i j} + \ket{1 \bar{i} \bar{j}}\right)$ ($\frac{1}{\sqrt{2}}\left(\ket{0 i j} - \ket{1 \bar{i} \bar{j}}\right)$). The key bits can be obtained by performing Z-basis measurements on the auxiliary systems $A_1$, $B_1$, and $C_1$, whose phase error rate can be obtained by performing X-basis measurements on these auxiliary systems. According to the analysis of Sec.~\ref{sec:GHZ}, the phase error rate expressed as Eq.~\eqref{eq:phase_error} can be obtained.
