L000434	
L000435	\subsection{Decoy-state method}\label{sec:dsm}
L000436	The phase errors rate $E_X$ in Eq.~\eqref{eq:phase_error} can be rewritten as
L000437	\begin{equation}
L000438	\begin{split}
L000439	E_X & = \sum_{k \in \text{odd}} P_\mu(k) \frac{Y_k}{Q_\mu} \\
L000440	& = 1- \sum_{k \in \text{even}} P_\mu(k) \frac{Y_k}{Q_\mu} \\
L000441	& \leq E_X^U = 1 - P_\mu(2) \frac{Y_2^L}{Q_\mu},
L000442	\end{split}
L000443	\end{equation}
L000444	where $P_\mu(k)$ is the probability that all parties emit $k$ photons, following a Poisson distribution with total intensity $\mu_\text{tot}$ as the parameter. $Y_2^L$ is the lower bound of the yield of two photons, which can be estimated by decoy-state method with the intensity set $\{ \mu , \nu , \omega , 0 \}$. Define
L000445	\begin{equation}
L000446	\begin{split}
L000447	\mu_\text{tot} &= \mu_a + \mu_b + \mu_c, \\
L000448	\nu_\text{tot} &= \nu_a + \mu_b + \nu_c, \\
L000449	\omega_\text{tot} &= \omega_a + \omega_b + \omega_c, \\
L000450	\mu_\text{tot} &> \nu_\text{tot} > \omega_\text{tot}.
L000451	\end{split}
L000452	\end{equation}
L000453	Here $\mu_a : \nu_a : \omega_a = \mu_b : \nu_b : \omega_b = \mu_c : \nu_c : \omega_c$ is assumed. Then
L000454	\begin{equation}
L000455	\begin{split}
L000456	e^{\mu_\text{tot}} Q_\mu &= Y_0 + 2\mu_\text{tot} Y_1 + \frac{\mu_\text{tot}^2}{2}Y_2 + \frac{\mu_\text{tot}^3}{6}Y_3 + \cdots, \\
L000457	e^{\nu_\text{tot}} Q_\nu &= Y_0 + 2\nu_\text{tot} Y_1 + \frac{\nu_\text{tot}^2}{2}Y_2 + \frac{\nu_\text{tot}^3}{6}Y_3 + \cdots, \\
L000458	e^{\omega_\text{tot}} Q_\omega &= Y_0 + 2\omega_\text{tot} Y_1 + \frac{\omega_\text{tot}^2}{2}Y_2 + \frac{\omega_\text{tot}^3}{6}Y_3 + \cdots, \\
L000459	Q_0 &= Y_0.
L000460	\end{split}
L000461	\end{equation}
L000462	Using the Gaussian-elimination method, we have
L000463	\begin{equation}
L000464	Y_2 \geq \frac{2}{G} \left( G_\nu Q_\nu + G_0 Q_0 - G_\mu Q_\mu - G_\omega Q_\omega \right),
L000465	\end{equation}
L000466	where
L000467	\begin{equation}
L000468	\begin{split}
L000469	G =& (\mu_\text{tot} -  \nu_\text{tot})( \nu_\text{tot} - \omega_\text{tot}) \mu_\text{tot} \nu_\text{tot}^2 \omega_\text{tot}(\mu_\text{tot}-\omega_\text{tot})>0,\\
L000470	G_{\nu} =& \mu_\text{tot} \nu_\text{tot} \omega_\text{tot} e^{\nu_\text{tot}}(\mu_\text{tot}^2 - \omega_\text{tot}^2 )>0,\\
L000471	G_0  =&(\mu_\text{tot}-\nu_\text{tot}) (\nu_\text{tot}-\omega_\text{tot})\nu_\text{tot}\\
L000472	&\left[\mu_\text{tot} (\mu_\text{tot}+ \nu_\text{tot}) - \omega_\text{tot}(\nu_\text{tot}+ \omega_\text{tot})\right]>0,\\
L000473	G_\mu =& (\nu_\text{tot}^2 - \omega_\text{tot}^2)\nu_\text{tot}^2\omega_\text{tot}e^{\mu_\text{tot}}>0, \\
L000474	G_\omega =& (\mu_\text{tot}^2 - \nu_\text{tot}^2)\mu_\text{tot} \nu_\text{tot}^2e^{\omega_\text{tot}}>0.
L000475	\end{split}
L000476	\end{equation}
L000477	Thus $Q_0G_0\geq0$ and
L000478	\begin{equation}
L000479	Y_2 \geq Y_2^L = \frac{2}{G} \left( G_\nu Q_\nu - G_\mu Q_\mu - G_\omega Q_\omega \right).
L000480	\end{equation}
L000481	Based on the yield of distillation of the pure 3-qubit GHZ state, the key rate of PM QCC protocol can be expressed as
L000482	\begin{equation} \label{eq:keyrate}
L000483	R = \left( \frac{2}{D} \right)^2 Q_\mu \left[1-fh(E_Z^{\max})-h(E^U_{X})\right],
L000484	\end{equation}
L000485	where $(2/D)^2$ is the prefactor induced by phase post-selection.
L000486	
L000487	\subsection{Finite-size analysis}\label{sec:Finite_size_analysis}
L000488	Given an observed quantity $\chi$, follow the Chernoff-Hoeffding method in Ref.~\cite{PRAZhang2017}, the upper bound and lower bound of the underlying expectation value are given by
L000489	\begin{equation}
L000490	\begin{split}
L000491	\mathbb{E}^L(\chi)&=\dfrac{\chi}{1+\delta^L},\\
L000492	\mathbb{E}^U(\chi)&=\dfrac{\chi}{1-\delta^U},
L000493	\end{split}
L000494	\end{equation}
L000495	where $\delta^{L(U)}$ is the solution of
L000496	\begin{equation}\label{eq:deltasolve}
L000497	\begin{split}
L000498	\left[\dfrac{e^{\delta^L}}{(1+\delta^L)^{1+\delta^L}}\right]^{\chi / (1+\delta^L)}&=\dfrac{1}{2}\epsilon,\\
L000499	\left[\dfrac{e^{-\delta^U}}{(1-\delta^U)^{1-\delta^U}}\right]^{\chi / (1-\delta^U)}&=\dfrac{1}{2}\epsilon.
L000500	\end{split}
L000501	\end{equation}
L000502	The $\epsilon$ is failure probability of the estimation $\mathbb{E}(\chi)\in [\mathbb{E}^L(\chi), \mathbb{E}^U(\chi)]$. When finite-size effects are considered, the lower bound of the yield of two-photon state is given by
L000503	\begin{equation}\label{eq:finit_key_y2}
L000504	Y_2^L = \frac{2}{G} \left( G_\nu Q_\nu^L - G_\mu Q_\mu^U - G_\omega Q_\omega^U \right),
L000505	\end{equation}
L000506	where $Q_\mu^U$ and $Q_\omega^U$ are the upper bounds of $Q_\mu$ and $Q_\omega$, respectively, and $Q_\nu^L$ is the lower bound of $Q_\nu$.
L000507	
L000508	\subsection{Simulation method and result}\label{sec:Simulation_method_and_result}
L000509	Firstly, we obtain the click probability in the PM QCC protocol, and then calculate the gain under the given information of the sender and the channel.  The intensity of coherent state prepared by Alice, Bob and Charlie are denoted as $\mu_A\in\{\mu_a, \nu_a, \omega_a\}$, $\mu_B\in\{\mu_b, \nu_b, \omega_b\}$ and $\mu_C\in\{\mu_c, \nu_c, \omega_c\}$, respectively. The transmittance from Alice, Bob, Charlie to the measuremnt site are denoted as $\eta_{A}$, $\eta_{B}$ and $\eta_{C}$.  The total detection efficiency of measuremnt site is $\eta_d$. The click probabilities of two measurement branches for each coherent pulse are given by
L000510	\begin{equation}
L000511	\begin{split}
L000512		p_{\mu_A,\mu_B}^\text{click} &= 1- e^{-\eta_A\eta_d \mu_A/2 - \eta_B\eta_d  \mu_B} + \\
L000513	&2 p_d e^{-\eta_A\eta_d  \mu_A/2 - \eta_B\eta_d  \mu_B}, \\
L000514		p_{\mu_A,\mu_C}^\text{click}&= 1- e^{-\eta_A\eta_d  \mu_A/2 - \eta_C\eta_d \mu_C} + \\
L000515	&2 p_d e^{-\eta_A\eta_d \mu_A/2 - \eta_C\eta_d  \mu_C},
L000516	\end{split}
L000517	\end{equation}
L000518	where $p_d$ represents the dark count rate of the single-photon detector. The gain can be written as
L000519	\begin{equation}
L000520		Q_{\mu_A,\mu_B,\mu_C} = p_{\mu_A,\mu_B}^\text{click} p_{\mu_A,\mu_C}^\text{click}.
L000521	\end{equation}
L000522	
L000523	The sending probabilities of signal state and two decoy states for each party are denoted as $p_{\mu}$, $p_{\nu}$, and $p_{\omega}$, respectively. The total number of rounds is denoted as $N$.  Thus, the number of rounds in which Alice, Bob, and Charlie simultaneously send signal and two decoy states are given by
L000524	\begin{equation}
L000525		\begin{split}
L000526			N_\mu &= N p_{\mu}^3, \\
L000527			N_\nu &= N p_{\nu}^3, \\
L000528			N_\omega &= N p_{\omega}^3.
L000529		\end{split}
L000530	\end{equation}
L000531	
L000532	The effective clicks for simultaneously sending signal and two decoy states are given by
L000533	\begin{equation}
L000534		\begin{split}
L000535			M_\mu &= N_{\mu} Q_{\mu_a,\mu_b,\mu_c} =  N_{\mu} Q_{\mu},\\
L000536			M_\nu &= N_{\nu} Q_{\nu_a,\nu_b,\nu_c} = N_{\nu} Q_{\nu}, \\
L000537			M_\omega &= N_{\omega} Q_{\omega_a,\omega_b,\omega_c} = N_{\omega} Q_{\omega}.
L000538		\end{split}
L000539	\end{equation}
L000540	
L000541	Based on the finite-key analysis method in Sec.~\ref{sec:Finite_size_analysis}, The statistical upper and lower bounds of the effective clicks can be calculated by the Chernoff bound method. Then the upper and lower bounds of the gain for each state can be obtained. By substituting it into Eq.~\eqref{eq:finit_key_y2}, the lower bound of the two-photon yield can be derived.
L000542	
L000543	The upper bound of the phase error can be written as
L000544	\begin{equation}\label{eq:simulation_ex}
L000545		E^U_X = 1 - e^{-\mu_\text{tot}} \frac{\mu_\text{tot}^2}{2 Y_2^L Q_\mu^L}.
L000546	\end{equation}
L000547	
L000548	The quantum bit error rate can be expressed by
L000549	\begin{equation}\label{eq:simulation_Ez}
L000550		E_Z^\text{max} = \max\{e^{AB}, e^{AC}\} + e_d,
L000551	\end{equation}
L000552	where $e_d$ is the misalignment error, $e^{AB}$ and $e^{AC}$ are intrinsic errors of two measurement branch caused by dark counts and the discretization of the phase slice, which are given by
L000553	\begin{equation}
L000554		\begin{split}
L000555		e^{AB} = &\frac{1}{p_{\mu_a,\mu_b}^\text{click}} \left[p_d + (\eta_{A}\eta_d \mu_a/2 + \eta_{B}\eta_d \mu_b)e_\delta \right]\\
L000556	& e^{-\eta_{A}\eta_d \mu_a/2 - \eta_{B}\eta_d \mu_b},\\
L000557		e^{AC} = &\frac{1}{p_{\mu_a,\mu_c}^\text{click}} \left[p_d + (\eta_{A}\eta_d \mu_a/2 + \eta_{C}\eta_d \mu_c)e_\delta \right] \\
L000558	&e^{-\eta_{A}\eta_d \mu_a/2 - \eta_{C}\eta_d \mu_c},\\
L000559		e_\delta = &\frac{\pi}{D} - \left(\frac{D}{\pi}\right)^2 \left( \sin \frac{\pi}{D} \right)^3.
L000560		\end{split}
L000561	\end{equation}
L000562	
L000563	Finally, the key rates can be obtained by substituting Eq.~\eqref{eq:simulation_ex} and Eq.~\eqref{eq:simulation_Ez} into Eq.~\eqref{eq:keyrate}. The simulation results for symmetric and asymmetric channels are given in Fig.~\ref{fig:keyratesimu}. In Fig.~\ref{fig:keyratesimu} (a), the key rates in symmetric fiber channels are simulated under the number of rounds $N$ of $10^{13}$, $10^{14}$, and $10^{15}$, respectively. In Fig.~\ref{fig:keyratesimu} (b), the key rates in asymmetric fiber channels are simulated where the distance from Alice to the measurement site is fixed at $\SI{75}{\km} $, while the distances from Bob and Charlie to the measurement site are vary from 0 to $\SI{75}{\km} $, respectively.
